let isTracking = false;
        let positions = [];
        let trackingInterval = null;
        let currentTarget = { x: 50, y: 50 };

        function startTracking() {
            document.getElementById('start-screen').classList.add('hidden');
            document.getElementById('tracking-screen').classList.remove('hidden');
            document.getElementById('results-screen').classList.add('hidden');
            isTracking = true;
            positions = [];

            moveTarget();
            trackingInterval = setInterval(() => {
                const dot = document.getElementById('tracking-dot');
                const rect = document.getElementById('tracking-area').getBoundingClientRect();
                const x = ((parseFloat(dot.style.left) / 100) * rect.width) + rect.left;
                const y = ((parseFloat(dot.style.top) / 100) * rect.height) + rect.top;
                positions.push({ x, y, targetX: currentTarget.x * rect.width / 100, targetY: currentTarget.y * rect.height / 100 });

                const dx = x - currentTarget.x * rect.width / 100;
                const dy = y - currentTarget.y * rect.height / 100;
                const drift = Math.sqrt(dx * dx + dy * dy);
                const score = Math.max(0, Math.min(100, Math.round(100 - drift)));
                document.getElementById('stability-score').textContent = score;

                dot.classList.remove('stable', 'tremor');
                if (score > 80) dot.classList.add('stable');
                else if (score < 60) dot.classList.add('tremor');
            }, 100);

            setTimeout(() => {
                if (isTracking) endTracking();
            }, 30000);
        }

        function moveTarget() {
            const targets = [
                { x: 20, y: 20 }, { x: 80, y: 20 },
                { x: 20, y: 80 }, { x: 80, y: 80 },
                { x: 50, y: 50 }
            ];
            currentTarget = targets[Math.floor(Math.random() * targets.length)];
            document.getElementById('target-1').style.left = currentTarget.x + '%';
            document.getElementById('target-1').style.top = currentTarget.y + '%';
        }

        function endTracking() {
            isTracking = false;
            clearInterval(trackingInterval);
            document.getElementById('tracking-screen').classList.add('hidden');
            document.getElementById('results-screen').classList.remove('hidden');

            const drifts = positions.map(p => {
                const dx = p.x - p.targetX;
                const dy = p.y - p.targetY;
                return Math.sqrt(dx * dx + dy * dy);
            });
            const avgDrift = drifts.reduce((a, b) => a + b, 0) / drifts.length;
            const peakDrift = Math.max(...drifts);
            const stability = Math.max(0, Math.round(100 - avgDrift * 2));

            document.getElementById('final-stability').textContent = stability;
            document.getElementById('avg-drift').textContent = avgDrift.toFixed(1);
            document.getElementById('peak-movement').textContent = peakDrift.toFixed(1);

            let assessment = 'Normal';
            if (stability < 50) assessment = 'High';
            else if (stability < 70) assessment = 'Moderate';
            else if (stability < 85) assessment = 'Mild';
            document.getElementById('assessment').textContent = assessment;
        }

        function resetTest() {
            document.getElementById('start-screen').classList.remove('hidden');
            document.getElementById('tracking-screen').classList.add('hidden');
            document.getElementById('results-screen').classList.add('hidden');
            document.getElementById('tracking-dot').style.left = '50%';
            document.getElementById('tracking-dot').style.top = '50%';
        }

        document.addEventListener('mousemove', (e) => {
            if (!isTracking) return;
            const dot = document.getElementById('tracking-dot');
            const rect = document.getElementById('tracking-area').getBoundingClientRect();
            const x = ((e.clientX - rect.left) / rect.width) * 100;
            const y = ((e.clientY - rect.top) / rect.height) * 100;
            dot.style.left = Math.max(5, Math.min(95, x)) + '%';
            dot.style.top = Math.max(5, Math.min(95, y)) + '%';
        });
